import functools

def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        build_idx = core.find('+')
        if build_idx != -1:
            core = core[:build_idx]
        pre_idx = core.find('-')
        if pre_idx != -1:
            pre = core[pre_idx+1:]
            core = core[:pre_idx]
        major, minor, patch = (int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def compare_pre(a, b):
        # a, b are lists of identifiers or None
        if a is None and b is None:
            return 0
        if a is None:
            return 1  # no prerelease > has prerelease
        if b is None:
            return -1
        for ia, ib in zip(a, b):
            ia_num = ia.isdigit()
            ib_num = ib.isdigit()
            if ia_num and ib_num:
                na, nb = int(ia), int(ib)
                if na != nb:
                    return -1 if na < nb else 1
            elif ia_num and not ib_num:
                return -1
            elif not ia_num and ib_num:
                return 1
            else:
                if ia != ib:
                    return -1 if ia < ib else 1
        if len(a) != len(b):
            return -1 if len(a) < len(b) else 1
        return 0

    def compare(v1, v2):
        p1 = parse(v1)
        p2 = parse(v2)
        for i in range(3):
            if p1[i] != p2[i]:
                return -1 if p1[i] < p2[i] else 1
        return compare_pre(p1[3], p2[3])

    return sorted(versions, key=functools.cmp_to_key(compare))

